import{_ as s,a0 as a,w as e,s as d,I as n,x as o,a1 as i,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"安卓編年史（29）：Android 5.0 Lollipop——有史以來最重要的安卓版本（3） | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（29）：Android 5.0 Lollipop——有史以來最重要的安卓版本（3） | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（29）：Android 5.0 Lollipop——有史以來最重要的安卓版本（3） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（29）：Android 5.0 Lollipop——有史以來最重要的安卓版本（3） | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/29 - The (updated) history of Android","title":"安卓編年史（29）：Android 5.0 Lollipop——有史以來最重要的安卓版本（3）","tag":"The history of Android","desc":""},"relativePath":"The history of Android/29 - The (updated) history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/29 - The (updated) history of Android.md"};function g(m,t,f,h,T,w){const p=a("Link");return e(),d("div",null,[t[22]||(t[22]=n("h1",{id:"安卓編年史-29-android-5-0-lollipop——有史以來最重要的安卓版本-3",tabindex:"-1"},[o("安卓編年史（29）：Android 5.0 Lollipop——有史以來最重要的安卓版本（3） "),n("a",{class:"header-anchor",href:"#安卓編年史-29-android-5-0-lollipop——有史以來最重要的安卓版本-3","aria-label":"Permalink to “安卓編年史（29）：Android 5.0 Lollipop——有史以來最重要的安卓版本（3）”"},"​")],-1)),t[23]||(t[23]=n("p",null,"毫不誇張地説，谷歌搜索在棒棒糖中無處不在。“持續開啓語音識別”這項特性讓用户可以在任何界面隨時説出“OK Google”，即時是在息屏狀態也沒有問題。谷歌應用依然是谷歌的首要主屏，這項特性是自奇巧時引入的。現在搜索欄也會顯示在新的最近應用界面。",-1)),t[24]||(t[24]=n("p",null,"Google Now 依然是最左側的主屏，但現在 Material Design 對它進行了大翻新，給了它一個色彩大膽的頭部以及重新設計的排版。",-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/10/play-store-1-1440x707.jpg",alt:""})],-1)),t[26]||(t[26]=n("p",null,"Play 商店遵從了和其它棒棒糖應用相似的軌跡。它在視覺上煥然疑一新，大膽的色彩，新排版，還有一個全新的佈局。通常這裏不會有什麼新增功能，就只是給一切換件新馬甲。",-1)),t[27]||(t[27]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/10/play2-1440x707.jpg",alt:""})],-1)),t[28]||(t[28]=n("p",null,"Play 商店的導航面板現在真的可以用於導航了，每個分類有各自的入口。棒棒糖也不再在操作欄放“更多”按鈕了，取而代之的是一個獨立的操作按鈕（通常是搜索），並且去掉了導航欄中多餘的選項。這給了用户一個單獨的地方來查找項目，而不用在兩個菜單中尋找搜索的地方。",-1)),t[29]||(t[29]=n("p",null,"棒棒糖還給了應用讓狀態欄透明的能力。這讓操作欄的顏色可以滲透到狀態欄，讓它只比周圍的界面暗一點點。一些界面甚至在頂部使用了全幅英雄圖片，同時顯示到了狀態欄上。",-1)),n("p",null,[i(p,{href:"https://cdn.arstechnica.net/wp-content/uploads/2016/10/2-1.jpg"},{default:l(()=>[...t[0]||(t[0]=[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/10/2-1-980x481.jpg",alt:""},null,-1)])]),_:1})]),t[30]||(t[30]=r('<p>谷歌日曆完全重寫了，獲得了很多新設計，也失去了很多特性。你不再能夠雙指縮放來調整時間視圖，月份視圖也從手機上消失了，周視圖從七天退化成了五天的視圖。在用户抱怨之後，谷歌將會花費接下來幾個版本的時間來重新添加回這裏面的一些特性。“谷歌日曆”還加強了“谷歌”部分，去除了直接在應用內添加第三方賬户的能力。非谷歌賬户現在需要從 Gamil 來添加。</p><p>儘管如此，它看起來還是很棒。在一些視圖上，月份開頭帶有頭圖，就像是真實的紙質日曆。帶有地點的事件會附帶顯示來自那個地點的照片。舉個例子，我的“去往舊金山”會顯示金門大橋。谷歌日曆還會從 Gamil 獲取事件並在你的日曆中顯示。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/9-1-1440x2560.jpg" alt=""></p><p>其它應用都可以套用基本相同的描述：功能上沒有太多新鮮的，但新設計換掉了奇巧中的灰色以大膽，明亮的色彩。環聊獲得了收取 Google Voice 信息的能力，時鐘應用的背景顏色會隨着每天時間的變化而改變。</p><h4 id="任務調度器鞭策應用生態成型" tabindex="-1">任務調度器鞭策應用生態成型 <a class="header-anchor" href="#任務調度器鞭策應用生態成型" aria-label="Permalink to “任務調度器鞭策應用生態成型”">​</a></h4><p>谷歌決定在棒棒糖中實施“伏特計劃（Project Volta）”，關注電量使用問題。谷歌從“電池史學家（Battery Historian）”開始，為自己和開發者創建了更多的電池追蹤工具。這個 python 腳本獲取所有的安卓電量日誌數據，並轉換成可讀，交互式的圖表。在這個新診斷工具的幫助下，谷歌將後台任務標記為主要的耗電大户。</p><p>在 2014 年的 I/O 大會上，這家公司注意到啓用飛行模式並關閉屏幕可以讓安卓手機待機將近一個月。但是，如果用户全部啓用並使用設備，它們沒法堅持一整天。結論就是如果你能讓一切都停止活動，你的電池表現就能好得多。</p><p>因此，谷歌創建了一個新 API，稱作“JobScheduler（任務調度器）”，這是個新的針對安卓後台任務的警察。在任務調度器出現之前，每個單獨的應用為它自己的後台進程負責，這意味着每個應用會獨立喚醒處理器和調製解調器，檢查連通性、組織資料庫、下載更新以及上傳日誌。所有東西都有它自己獨立的定時器，所以你的手機會一直被喚醒。有了任務調度器，後台任務從無組織的混亂，轉變為統一的批處理，有有序的後台進程處理窗口。</p><p>任務調度器可以讓應用指定它們的任務所需的條件（連通性、Wi-Fi、接入電源等等），它會在那些條件滿足的時候發送一條通知。這就像是推送郵件和每五分鐘檢查一次郵件的區別……但是帶上任務需求的。谷歌還開始給後台任務推進一個“懶”實現。如果一些事情可以推遲到設備處於 Wi-Fi，接入電源以及待機狀態，那它就應該等到那時候執行。你現在可以看到這一策略的成果，在 Wi-Fi 下，你可以將安卓手機接入電源，並且只有在_這種條件下_它才會開始下載應用更新。你通常不需要立即下載應用更新，最好的時候是等到用户有無限的電源和網絡的時候進行。</p><h4 id="開機設置獲得面向未來的新設計" tabindex="-1">開機設置獲得面向未來的新設計 <a class="header-anchor" href="#開機設置獲得面向未來的新設計" aria-label="Permalink to “開機設置獲得面向未來的新設計”">​</a></h4><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/25-1-1440x707.jpg" alt=""></p><p>開機設置經過了大翻新，它不止是為了跟上 Material Design 指南，還是“面向未來”的，這樣不管未來谷歌採用什麼新的登錄和驗證方案，它都能夠適應。記住，寫“安卓編年史”的部分原因就是一些舊版安卓已經不再能工作了。這些年來，谷歌已經為用户升級了更佳加密的驗證方案以及二次驗證，但添加這些新的登錄要求破壞了舊客户端的兼容性。很多安卓特性要求訪問谷歌雲設施，所以你沒法登錄的話，像安卓 1.0 的 Gmail 這樣的就沒法工作了。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/26-1440x1454.jpg" alt=""></p><p>在棒棒糖中，開機設置工作的前幾個界面和之前的很像。你可以看到“歡迎使用安卓界面”以及一些設置數據和 Wi-Fi 連接的選項。但在這個界面之後就有了變化。一旦棒棒糖連接到了互聯網，它會連接到谷歌的服務器來“檢查更新”。這並不是檢查系統或應用的更新，是在檢查即將執行的設置工作的更新。安卓下載了最新版本的設置，_然後_它會要求你登錄你的谷歌賬户。</p>',14)),n("p",null,[t[2]||(t[2]=o("在今天登錄進棒棒糖和奇巧的時候這個好處很明顯。有可以可升級的設置流程，“2014”的棒棒糖系統可以適應 2016 的改進，像是谷歌新的“",-1)),i(p,{href:"http://arstechnica.com/gadgets/2016/06/googles-new-two-factor-authentication-system-tap-yes-to-log-in/"},{default:l(()=>[...t[1]||(t[1]=[o("觸碰登錄",-1)])]),_:1}),t[3]||(t[3]=o("”雙重認證。奇巧在這就卡住了，但幸運的是它有個“瀏覽器登錄”可以解決雙重認證的問題。",-1))]),t[31]||(t[31]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2014/10/setup3.jpg",alt:""})],-1)),n("p",null,[t[6]||(t[6]=o("棒棒糖的開機設置對將你的谷歌賬户和密碼放在單獨的頁面持極端立場。",-1)),i(p,{href:"https://www.theguardian.com/technology/2016/may/24/google-passwords-android"},{default:l(()=>[...t[4]||(t[4]=[o("谷歌討厭密碼",-1)])]),_:1}),t[7]||(t[7]=o("並提供了一些",-1)),i(p,{href:"https://www.theguardian.com/technology/2016/may/24/google-passwords-android"},{default:l(()=>[...t[5]||(t[5]=[o("實驗性的方式",-1)])]),_:1}),t[8]||(t[8]=o("來不用單獨頁面登錄到谷歌。如果你的賬户設置為不使用密碼，棒棒糖可以跳過密碼頁面。如果你設置了雙重認證，設置頁面就會進入到“輸入雙因素碼”的設置流程。每個登錄部分都是在單獨的一個頁面，所以設置流程是模組化的。頁面可以隨要求添加或移除。",-1))]),t[32]||(t[32]=r('<p><img src="https://cdn.arstechnica.net/wp-content/uploads/2014/10/setup5.jpg" alt=""></p><p>開機設置還給了用户對應用還原的控制。安卓在這之前也提供了一些數據還原，但那是無法理解的，因為它僅僅只是在沒有任何用户輸入的情況下選擇你的一台設備並開始恢復。開機設置流程中的一個新界面讓用户可以看到在雲端的設備配置集合，並選擇合適的那個。你還可以選擇要從那個備份還原的應用。備份有應用，你的主屏佈局，以及一些小設置如 Wi-Fi 熱點。它不是完全的應用數據備份。</p><h4 id="設置" tabindex="-1">設置 <a class="header-anchor" href="#設置" aria-label="Permalink to “設置”">​</a></h4><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/settings-1-1440x848.jpg" alt=""></p><p>設置從暗色主題切換到了亮色。除了新外觀，它還有方便的搜索功能。每個界面用户都能訪問放大鏡，讓他們可以更容易地找到難找的選項。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/2014-11-11-16.45.47-1440x2560.png" alt=""></p><p>這裏有一些和伏特計劃有關的額設置。“網絡限制”允許用户將一個 Wi-Fi 連接標記為計費的，讓任務調度器處理後台處理時避免使用它。同時作為伏特計劃的一部分，添加了一個“節電模式”。它會限制後台任務並限制 CPU 性能，給你更長的續航但更慢的設備。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2014/11/user1.jpg" alt=""></p><p>多用户支持已經出現在安卓平板中有一段時間了，但棒棒糖終於將它帶到了安卓手機上。設置界面添加了一個新的“用户”頁面，讓你添加額外的賬户或設置一個“訪客”賬户。訪客賬户是臨時的——它們可以一次點擊輕鬆刪除。它不會像正常賬户那樣嘗試下載關聯到你賬户的每個應用，因為它註定要在不久後被刪除。</p><hr><p>作者簡介：</p><p>Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。</p><hr>',13)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),i(p,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/29/"},{default:l(()=>[...t[9]||(t[9]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/29/",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=o("作者：",-1)),i(p,{href:"http://arstechnica.com/author/ronamadeo"},{default:l(()=>[...t[11]||(t[11]=[o("RON AMADEO",-1)])]),_:1}),t[15]||(t[15]=o(" 譯者：",-1)),i(p,{href:"https://github.com/alim0x"},{default:l(()=>[...t[12]||(t[12]=[o("alim0x",-1)])]),_:1}),t[16]||(t[16]=o(" 校對：",-1)),i(p,{href:"https://github.com/wxy"},{default:l(()=>[...t[13]||(t[13]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=o("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[17]||(t[17]=[o("LCTT",-1)])]),_:1}),t[20]||(t[20]=o(" 原創編譯，",-1)),i(p,{href:"https://linux.cn/"},{default:l(()=>[...t[18]||(t[18]=[o("Linux中國",-1)])]),_:1}),t[21]||(t[21]=o(" 榮譽推出",-1))])])}const C=s(u,[["render",g]]);export{y as __pageData,C as default};
